def dice_sum_prob(n, faces, target):
    dp = [1.0] + [0.0] * (n * faces)
    for _ in range(n):
        nd = [0.0] * (n * faces + 1)
        for s, p in enumerate(dp):
            if p:
                for f in range(1, faces + 1):
                    if s + f <= n * faces: nd[s + f] += p / faces
        dp = nd
    return dp[target] if 0 <= target <= n * faces else 0.0

