double diceSumProb(int n, int f, int target) {
    if (target < 0 || target > n * f) return 0.0; vector<double> dp(n * f + 1, 0.0); dp[0] = 1.0;
    for (int k = 0; k < n; k++) { vector<double> nd(n * f + 1, 0.0); for (int s = 0; s <= n * f; s++) if (dp[s] > 0) for (int x = 1; x <= f && s + x <= n * f; x++) nd[s + x] += dp[s] / f; dp = nd; }
    return dp[target];
}
